/* Remuneração operacional sobre a Frequência existente, sem folha legal automática. */
(()=>{'use strict';const R=MartinsRemuneracao,P=MartinsPersistenciaRdo,H=MartinsRh,J=MartinsJornada,G=MartinsGastosObras,F=MartinsFinanceiro,$=id=>document.getElementById(id);if(!$('view-colaboradores'))return;
const css=document.createElement('style');css.textContent='#subview-remuneracao-colab .pay-row{padding:12px 0;border-top:1px solid #cbd5e1}#subview-remuneracao-colab h4{font-weight:800;margin-top:12px}#subview-remuneracao-colab input[type=checkbox]{width:auto;display:inline-block;margin-right:8px}#pay-dialog{width:min(740px,calc(100vw - 20px));max-height:88vh;overflow:auto;border:1px solid #cbd5e1;border-radius:14px;padding:18px}#pay-dialog::backdrop{background:#020617bb}#pay-dialog p{font-size:12px;line-height:1.6;white-space:pre-wrap}#pay-dialog label{display:block;font-size:12px;font-weight:700;margin:12px 0}#pay-dialog input,#pay-dialog select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px}#pay-dialog button{min-height:44px;padding:10px;border-radius:8px;background:#0f172a;color:#fbbf24;font-weight:700;font-size:12px;margin:5px}#pay-dialog [hidden]{display:none!important}#pay-review{white-space:pre-wrap}#pay-drawer{min-height:44px;width:100%;text-align:left;padding:10px;color:#334155;font-size:12px;font-weight:700}@media print{#subview-remuneracao-colab,#pay-dialog{display:none!important}}';document.head.append(css);
const panel=document.createElement('section');panel.id='subview-remuneracao-colab';panel.className='mf-box hidden';panel.innerHTML=`<h2>Remuneração, Diárias e Vales</h2><p>Apuração operacional para conferência. Usa apenas a Frequência Diária; não soma Planejamento ou RDO. Não calcula folha legal, encargos, férias, 13º ou descontos trabalhistas. Registrar uma despesa paga significa declarar um pagamento já realizado, sem executar transferência.</p><button id="pay-refresh" type="button">Atualizar fontes</button><button id="pay-frequency" type="button">Conferir Frequência Diária</button><label>Colaborador (inclui inativos para períodos anteriores)<select id="pay-person"></select></label><p id="pay-reference"></p><button id="pay-edit-person" type="button">Editar cadastro / remuneração</button><p id="pay-status" class="mf-message" role="status"></p><div id="pay-private"><details id="pay-advance-box"><summary style="font-weight:800;cursor:pointer;padding:12px">Vales e adiantamentos</summary><div class="mf-grid"><label>Data em que o vale foi entregue<input id="pay-advance-date" type="date"></label><label>Valor do vale (R$)<input id="pay-advance-value" type="number" min="0.01" step="0.01"></label></div><label>Motivo<input id="pay-advance-reason" maxlength="300"></label><label>Registro financeiro<select id="pay-advance-mode"><option value="controle">Somente controle do RH — conciliar antes do desconto</option><option value="vincular">Vincular a despesa já paga no Financeiro</option><option value="registrar_pago">Criar registro de despesa já paga (sem transferência)</option></select></label><div id="pay-advance-existing" hidden><label>Despesa de mão de obra já paga<select id="pay-advance-ledger"></select></label></div><div id="pay-advance-finance" hidden><div class="mf-grid"><label>Empresa responsável<input id="pay-advance-company" maxlength="300"></label><label>Conta utilizada<select id="pay-advance-account"></select></label><label>Obra<select id="pay-advance-work"></select></label><label>Centro de custo<input id="pay-advance-center" maxlength="300" value="Mão de obra"></label></div><label><input id="pay-advance-paid" type="checkbox"> Confirmo que este valor já foi entregue. Não há transferência por esta tela.</label></div><p>Limite: 40% do bruto da Frequência já trabalhado no mês da entrega, até a data do vale. Todos os vales não cancelados do mês contam, inclusive já descontados. Selecione a regra de diária e jornada em Apuração do período. Extras ainda não aprovadas não ampliam o limite. Mensalistas exigem conferência e exceção administrativa.</p><label><input id="pay-advance-duplicate" type="checkbox"> Conferi possível vale repetido de mesmo valor, pessoa e data.</label><label><input id="pay-advance-override" type="checkbox"> Sou administrador e autorizo exceder os 40%.</label><label>Justificativa da exceção administrativa<input id="pay-advance-justification" maxlength="300"></label><button id="pay-advance-prepare" type="button">Conferir vale</button><p id="pay-advance-message" class="mf-message" role="status"></p><div id="pay-advances"></div></details><h3 style="margin-top:18px">Apuração do período</h3><div class="mf-grid"><label>Início<input id="pay-start" type="date"></label><label>Fim (até hoje)<input id="pay-end" type="date"></label><label>Diárias — regra explícita<select id="pay-daily-rule"><option value="">Selecione para diaristas</option><option value="integral">Diária integral por dia com presença</option><option value="proporcional">Proporcional às horas de presença</option></select></label><label>Jornada de referência da diária (horas)<input id="pay-normal-hours" type="number" min="0.25" max="24" step="0.25" value="8"></label></div><p>Diária/hora usa dias com status Presente. Ausências e dias sem apontamento ficam identificados para revisão. O cálculo operacional não decide se uma ausência deve ser remunerada por regra legal.</p><label>Para mensalistas: base aprovada para este período (R$)<input id="pay-monthly-base" type="number" min="0" step="0.01" placeholder="Informe explicitamente; não calculada por faltas"></label><h4>Horas extras conferidas</h4><p>Adicione somente horas extras aprovadas, separadas das horas regulares. Informe o valor da hora extra em reais; nenhum percentual legal é presumido. Intervalos de 15 minutos.</p><div id="pay-extra-lines"></div><button id="pay-add-extra" type="button">+ Adicionar hora extra</button><h4>Vales a descontar</h4><p>Selecione os vales deste colaborador, conciliados com despesa paga. O desconto é feito uma única vez. Vales anteriores ao início podem ser usados se ainda estiverem disponíveis.</p><div id="pay-advance-checks"></div><button id="pay-preview" type="button">Calcular / conferir extrato</button><button id="pay-export" type="button">Exportar extrato CSV</button><p id="pay-calculation-message" class="mf-message" role="status"></p><div id="pay-calculation"></div><h3>Gerar conta a pagar após conferência</h3><p>Gera somente o líquido como despesa pendente. Vales conciliados já constam como despesa paga; não são lançados novamente. O gasto total é bruto quando vales e saldo estão corretamente registrados. Conferir rateios e centros de custo.</p><div class="mf-grid"><label>Empresa responsável<input id="pay-company" maxlength="300"></label><label>Conta para o saldo a pagar<select id="pay-account"></select></label><label>Vencimento<input id="pay-due" type="date"></label><label>Destino do saldo líquido<select id="pay-allocation-mode"><option value="admin">Administração / sem obra</option><option value="work">Uma obra</option><option value="split">Rateio manual entre obras</option></select></label></div><div id="pay-single" hidden><label>Obra<select id="pay-work"></select></label><label>Centro de custo<input id="pay-center" maxlength="300" value="Mão de obra"></label></div><div id="pay-split" hidden><div id="pay-allocations"></div><button id="pay-add-allocation" type="button">+ Adicionar rateio</button></div><label><input id="pay-reviewed" type="checkbox"> Conferi Frequência, vigências, regra de cálculo, horas extras, vales e rateios.</label><button id="pay-prepare-close" type="button">Conferir fechamento e conta a pagar</button><p>Gerar conta exige acesso ao Financeiro. Líquido zero registra o fechamento sem criar conta de valor zero.</p><h3 style="margin-top:18px">Histórico dos fechamentos</h3><div id="pay-history"></div></div>`;$('view-colaboradores').append(panel);
const tab=document.createElement('button');tab.id='subtab-btn-remuneracao-colab';tab.type='button';tab.className='subtab-colab-btn px-4 py-2.5 text-xs font-semibold text-slate-500 border-b-2 border-transparent shrink-0';tab.textContent='Remuneração e Vales';$('subtab-btn-uniformes-colab')?.after(tab);
const dialog=document.createElement('dialog');dialog.id='pay-dialog';dialog.setAttribute('aria-label','Conferir operação de remuneração');dialog.innerHTML='<h3 style="font-weight:800">Conferir registro de RH</h3><p id="pay-review"></p><label id="pay-link-label" hidden>Despesa já paga para conciliar<select id="pay-link-ledger"></select></label><label id="pay-reason-label" hidden>Motivo do estorno<input id="pay-reason" maxlength="300"></label><p id="pay-dialog-message" class="mf-message" role="status"></p><button id="pay-confirm" type="button">Confirmar registro</button><button id="pay-back" type="button">Voltar sem alterar</button>';document.body.append(dialog);
let request=null,busy=false,base=null,lastCalc=null,exportUrl=null;const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),br=d=>d?.split('-').reverse().join('/')||'Não informado',clock=d=>new Date(d).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}),value=id=>$(id)?.value||'';
function actor(finance=false){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!(finance?R.canFinance(u):R.canRead(u))||!session||!id(u)||id(u)!==id(session)||u.perfil!==session.perfil||session.status==='Inativo')throw Error(finance?'Confirmação restrita ao RH/Financeiro autorizado.':'Acesso restrito ao RH / Administração autorizada.');return u.usuario||u.email||u.nome;}
function sources(){const specs=[['people',H.EMPLOYEES,initialColaboradores],['frequency',J.KEYS.frequency,{}],['ledger',G.KEY,[]],['accounts',F.ACCOUNTS,[]],['works','cm_dados_obras_v2',dadosObras],['advances',R.ADVANCES,[]],['closings',R.CLOSINGS,[]]],s={},snap=[];for(const [name,key,fallback]of specs){P.guard(localStorage,key);const x=P.snapshot(localStorage,key,fallback);s[name]=x.data;snap.push({name,...x});}R.sources(s);return {s,snap,signature:P.canonical(snap.map(x=>[x.key,x.raw]))};}
function opts(select,rows,first){const old=select.value;select.replaceChildren(new Option(first,''));for(const r of rows)select.add(new Option(r.label,r.id));if([...select.options].some(o=>o.value===old))select.value=old;}
function paidOptions(s){return s.ledger.filter(r=>r.tipo==='despesa'&&r.status==='pago'&&r.categoria==='Mão de obra'&&!r.rhValeId&&!r.rhFechamentoId).map(r=>({id:r.id,label:br(r.pagoEm)+' · '+r.favorecido+' · '+money(r.valorCentavos)+' · '+r.empresa+' / '+r.descricao}));}
function selectPeople(s){opts($('pay-person'),s.people.map(c=>({id:String(c.id),label:c.nome+(c.apelido?' ('+c.apelido+')':'')+' / '+c.id+' · '+c.status})),'Selecione o colaborador');}
function allocations(){const mode=value('pay-allocation-mode');if(mode==='admin')return [];if(mode==='work'){if(!value('pay-work'))throw Error('Selecione a obra do saldo líquido');if(!lastCalc)throw Error('Calcule o extrato antes de ratear');return [{obra:value('pay-work'),centroCusto:value('pay-center'),valor:(lastCalc.liquidoCentavos/100).toFixed(2)}];}const rows=[...$('pay-allocations').children];if(!rows.length)throw Error('Adicione os rateios ou escolha Administração');return rows.map(row=>({obra:row.querySelector('select').value,centroCusto:row.querySelector('[data-field=center]').value,valor:row.querySelector('[data-field=value]').value}));}
function calcInput(){return {colaboradorId:value('pay-person'),inicio:value('pay-start'),fim:value('pay-end'),regraDiaria:value('pay-daily-rule'),jornadaHoras:value('pay-normal-hours'),baseMensal:value('pay-monthly-base'),empresa:value('pay-company').trim(),vales:[...$('pay-advance-checks').querySelectorAll('input:checked')].map(x=>x.value),extras:[...$('pay-extra-lines').children].map(row=>({data:row.querySelector('input[type=date]').value,horas:row.querySelector('[data-field=hours]').value,valorHora:row.querySelector('[data-field=value]').value}))};}
function showCalc(calc){lastCalc=calc;const box=$('pay-calculation');box.replaceChildren();const total=document.createElement('p');total.style.fontWeight='800';total.textContent=calc.nome+' · '+br(calc.inicio)+' a '+br(calc.fim)+' · '+calc.diasPresentes+' dia(s) presente(s) · '+calc.horasRegulares+'h regulares';box.append(total);const amounts=document.createElement('p');amounts.textContent='Base: '+money(calc.baseCentavos)+' · Extras: '+money(calc.extrasCentavos)+' · Bruto: '+money(calc.brutoCentavos)+' · Vales: '+money(calc.valesCentavos)+' · Líquido: '+money(calc.liquidoCentavos);box.append(amounts);for(const warning of calc.avisos){const p=document.createElement('p');p.className='mf-message';p.textContent=warning;box.append(p);}const detail=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Conferir dias, horas, valores e obras da Frequência';detail.append(summary);for(const l of calc.linhas){const p=document.createElement('p');p.textContent=br(l.data)+' · '+l.status+' · '+l.minutos/60+'h · referência '+money(l.referenciaCentavos)+' / '+l.tipo+' · base do dia '+money(l.valorCentavos)+' · '+l.alocacoes.map(a=>a.obra+' '+a.horas+'h').join('; ');detail.append(p);}if(calc.tipo==='mensal'){const p=document.createElement('p');p.textContent='Base mensal manual do período; os valores diários acima não distribuem esse valor.';detail.append(p);}box.append(detail);}
function exportCalc(calc,name='martins-extrato-remuneracao.csv'){if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(new Blob([R.csv(calc)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=exportUrl;a.download=name;document.body.append(a);a.click();a.remove();}
function renderAdvances(s){$('pay-advances').replaceChildren();$('pay-advance-checks').replaceChildren();for(const v of s.advances.filter(v=>v.colaboradorId===value('pay-person')).slice().reverse()){const row=document.createElement('div');row.className='pay-row';const p=document.createElement('p'),fin=s.ledger.find(r=>r.id===v.financeiroId);p.textContent=br(v.data)+' · '+money(v.valorCentavos)+' · '+v.motivo+' · '+v.status+' · '+(fin?fin.status+' em '+br(fin.pagoEm)+' / '+fin.conta+' / '+fin.empresa:'Sem conciliação financeira');row.append(p);if(v.status==='aberto'){if(!v.financeiroId){const b=document.createElement('button');b.type='button';b.textContent='Conciliar com despesa já paga';b.onclick=()=>prepareAction('link',v.id);row.append(b);}const b=document.createElement('button');b.type='button';b.textContent='Estornar registro do vale';b.onclick=()=>prepareAction('cancelAdvance',v.id);row.append(b);const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=v.id;check.disabled=!fin||fin.status!=='pago';label.append(check,document.createTextNode(br(v.data)+' · '+money(v.valorCentavos)+' · '+v.motivo+(check.disabled?' — conciliar antes de descontar':'')));$('pay-advance-checks').append(label);}if(v.limite){const info=document.createElement('p');info.textContent='Período '+v.limite.periodo+' · bruto '+money(v.limite.brutoCentavos)+' · limite '+money(v.limite.limiteCentavos)+(v.autorizacaoExcecao?' · Exceção autorizada por '+v.autorizacaoExcecao.por+': '+v.autorizacaoExcecao.motivo:'');row.append(info);}const detail=document.createElement('details'),summary=document.createElement('summary'),history=document.createElement('p');summary.textContent='Histórico do vale';history.textContent=v.historico.map(h=>h.acao+' por '+h.por+' em '+clock(h.em)+(h.motivo?' · '+h.motivo:'')).join('; ');detail.append(summary,history);row.append(detail);$('pay-advances').append(row);}if(!$('pay-advances').children.length)$('pay-advances').textContent='Sem vales cadastrados para este colaborador.';if(!$('pay-advance-checks').children.length)$('pay-advance-checks').textContent='Sem vales disponíveis.';}
function renderHistory(s){$('pay-history').replaceChildren();for(const c of s.closings.filter(c=>c.colaboradorId===value('pay-person')).slice().reverse()){const row=document.createElement('div');row.className='pay-row';const p=document.createElement('p'),l=s.ledger.find(r=>r.id===c.financeiroId);p.textContent=c.id+' · '+br(c.inicio)+' a '+br(c.fim)+' · '+c.status+' · '+c.empresa+' · líquido '+money(c.calculo.liquidoCentavos)+' · '+(l?'Financeiro: '+l.status+' / '+l.conta+' / vence '+br(l.vencimento):'Sem conta: líquido zero');row.append(p);for(const [label,action]of [['Ver extrato salvo',()=>showCalc(c.calculo)],['Exportar extrato salvo',()=>exportCalc(c.calculo,c.id+'.csv')]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>{try{actor();action();}catch(e){$('pay-status').textContent=e.message;}};row.append(b);}if(c.status==='fechado'){const b=document.createElement('button');b.type='button';b.textContent='Estornar fechamento pendente';b.onclick=()=>prepareAction('reverse',c.id);row.append(b);}const details=document.createElement('details'),summary=document.createElement('summary'),history=document.createElement('p');summary.textContent='Histórico do fechamento';history.textContent=c.historico.map(h=>h.acao+' por '+h.por+' em '+clock(h.em)+(h.motivo?' · '+h.motivo:'')).join('; ');details.append(summary,history);row.append(details);$('pay-history').append(row);}if(!$('pay-history').children.length)$('pay-history').textContent='Nenhum fechamento para este colaborador.';}
function refresh(){$('pay-advance-override').disabled=!R.canAuthorizeAdvance(currentLoggedUser);base=null;lastCalc=null;try{actor();const s=sources();$('pay-private').hidden=false;selectPeople(s.s);const accounts=s.s.accounts.map(c=>({id:c.id,label:c.nome+' / '+c.tipo}));for(const id of ['pay-account','pay-advance-account'])opts($(id),accounts,'Selecione uma conta');const works=Object.keys(s.s.works).sort().map(w=>({id:w,label:w}));opts($('pay-work'),works,'Selecione uma obra');opts($('pay-advance-work'),works,'Sem obra — Administração');opts($('pay-advance-ledger'),paidOptions(s.s),'Selecione despesa já paga');$('pay-reference').textContent='Selecione o colaborador para consultar a referência salarial.';if(value('pay-person')){const c=H.person(s.s.people,value('pay-person'));try{$('pay-reference').textContent='Referências: '+R.schedule(c).map(r=>money(r.centavos)+' / '+r.tipo+' desde '+br(r.vigencia)).join('; ');}catch(e){$('pay-reference').textContent=e.message;}}renderAdvances(s.s);renderHistory(s.s);$('pay-status').textContent='';base=s;}catch(e){$('pay-private').hidden=true;$('pay-reference').textContent='';$('pay-person').replaceChildren();$('pay-status').textContent=e.message;}}
function review(text){$('pay-review').textContent=text;$('pay-link-label').hidden=request.kind!=='link';$('pay-reason-label').hidden=!['reverse','cancelAdvance'].includes(request.kind);$('pay-reason').value='';$('pay-dialog-message').textContent='';dialog.showModal();}
$('pay-advance-prepare').onclick=()=>{try{const mode=value('pay-advance-mode'),by=actor(mode!=='controle'),s=sources();if(!base||s.signature!==base.signature)throw Error('Fontes alteradas; atualize antes de registrar');const input={colaboradorId:value('pay-person'),data:value('pay-advance-date'),valor:value('pay-advance-value'),motivo:value('pay-advance-reason'),modo:mode,financeiroId:value('pay-advance-ledger'),empresa:value('pay-advance-company'),contaId:value('pay-advance-account'),obra:value('pay-advance-work'),centroCusto:value('pay-advance-center'),cientePago:$('pay-advance-paid').checked,regraDiaria:value('pay-daily-rule'),jornadaHoras:value('pay-normal-hours'),cienteDuplicidade:$('pay-advance-duplicate').checked,autorizarExcecao:$('pay-advance-override').checked,justificativaExcecao:value('pay-advance-justification')},id='VALE-'+P.newId(),next=R.addAdvance(s.s,input,by,{id,user:currentLoggedUser}),v=next.advance,person=H.person(s.s.people,v.colaboradorId);request={kind:'advance',input,id,expected:s.signature};review('Bruto já trabalhado: '+money(v.limite.brutoCentavos)+' · Limite 40%: '+money(v.limite.limiteCentavos)+' · Acumulado com este vale: '+money(v.limite.novoAcumuladoCentavos)+'\n'+(v.autorizacaoExcecao?'EXCEÇÃO ADMINISTRATIVA: '+v.autorizacaoExcecao.motivo+'\n':'')+person.nome+' / '+v.colaboradorId+'\nVale: '+money(v.valorCentavos)+' · '+br(v.data)+'\n'+v.motivo+'\n'+(mode==='controle'?'Somente controle de RH. Será necessária conciliação antes do desconto.':mode==='vincular'?'Vincular despesa paga existente, sem criar nova despesa.':'Registrar no Financeiro como valor JÁ PAGO, sem transferência.')+(v.financeiroId?'\nRegistro financeiro: '+next.ledger.find(r=>r.id===v.financeiroId).favorecido+' / '+next.ledger.find(r=>r.id===v.financeiroId).empresa+' / '+next.ledger.find(r=>r.id===v.financeiroId).conta:'')+'\nNenhum pagamento bancário será executado.');}catch(e){$('pay-advance-message').textContent=e.message;}};
function prepareAction(kind,id){try{const s=sources(),v=kind==='reverse'?s.s.closings.find(c=>c.id===id):s.s.advances.find(v=>v.id===id);if(!v)throw Error('Registro não encontrado');actor(kind==='reverse'||kind==='link'||Boolean(v.financeiroId));request={kind,id,expected:s.signature};if(kind==='link')opts($('pay-link-ledger'),paidOptions(s.s),'Selecione despesa compatível já paga');review((kind==='reverse'?'Estornar fechamento '+id:kind==='link'?'Conciliar vale '+id:'Estornar registro do vale '+id)+'\n'+v.nome+'\n'+(kind==='reverse'?'Somente quando o saldo a pagar ainda não estiver pago. A conta pendente será cancelada e os vales voltam a ficar disponíveis; despesas dos vales permanecem pagas.':kind==='link'?money(v.valorCentavos)+' em '+br(v.data)+'. Selecione a despesa já paga, com mesmo valor/data. Não cria nova despesa.':v.modo==='registrar_pago'?'O registro de despesa criado por este vale será cancelado. Não devolve dinheiro por esta tela.':'O controle do vale será estornado. Despesa preexistente vinculada será preservada, liberando o vínculo.')+'\nO histórico será mantido.');}catch(e){$('pay-status').textContent=e.message;}}
$('pay-preview').onclick=()=>{try{actor();const s=sources();showCalc(R.calculate(s.s,calcInput()));$('pay-calculation-message').textContent='Prévia: nenhuma conta foi gerada.';}catch(e){lastCalc=null;$('pay-calculation').replaceChildren();$('pay-calculation-message').textContent=e.message;}};
$('pay-export').onclick=()=>{try{actor();const calc=R.calculate(sources().s,calcInput());showCalc(calc);exportCalc(calc);}catch(e){$('pay-calculation-message').textContent=e.message;}};
$('pay-prepare-close').onclick=()=>{try{const by=actor(true),s=sources();const raw=calcInput(),calc=R.calculate(s.s,raw);showCalc(calc);const input={...raw,contaId:value('pay-account'),vencimento:value('pay-due'),rateios:allocations(),ciente:$('pay-reviewed').checked},id='RH-FECH-'+P.newId();const next=R.close(s.s,input,by,{id});request={kind:'close',input,id,expected:s.signature};review(calc.nome+' / '+calc.colaboradorId+'\nPeríodo: '+br(calc.inicio)+' a '+br(calc.fim)+'\nBase '+money(calc.baseCentavos)+' + Extras '+money(calc.extrasCentavos)+' = Bruto '+money(calc.brutoCentavos)+'\nVales já pagos: '+money(calc.valesCentavos)+'\nLíquido a pagar: '+money(calc.liquidoCentavos)+'\nEmpresa: '+input.empresa+'\n'+(next.closing.financeiroId?'Conta: '+next.ledger.find(r=>r.id===next.closing.financeiroId).conta+' · vencimento '+br(input.vencimento):'Líquido zero: nenhuma conta será criada')+'\nDestino do líquido: '+(input.rateios.length?input.rateios.map(r=>r.obra+' / '+r.centroCusto+': '+r.valor).join('; '):'Administração')+'\nAvisos: '+(calc.avisos.join('; ')||'Sem avisos adicionais')+'\nConfirmar gera registro pendente. Não efetua pagamento.');}catch(e){$('pay-calculation-message').textContent=e.message;}};
$('pay-confirm').onclick=async()=>{if(busy||!request)return;busy=true;const req=structuredClone(request),reason=value('pay-reason'),link=value('pay-link-ledger');$('pay-confirm').disabled=$('pay-back').disabled=true;let saved=false;try{await P.withLock(navigator.locks,()=>{const s=sources();if(s.signature!==req.expected)throw Error('Dados alterados após a conferência; reabra a operação');const v=s.s.advances.find(v=>v.id===req.id),financial=req.kind==='close'||req.kind==='reverse'||req.kind==='link'||req.kind==='advance'&&req.input.modo!=='controle'||req.kind==='cancelAdvance'&&Boolean(v?.financeiroId),by=actor(financial);let next;if(req.kind==='advance')next=R.addAdvance(s.s,req.input,by,{id:req.id,user:currentLoggedUser});else if(req.kind==='link')next=R.linkAdvance(s.s,req.id,link,by);else if(req.kind==='cancelAdvance')next=R.cancelAdvance(s.s,req.id,reason,by);else if(req.kind==='reverse')next=R.reverse(s.s,req.id,reason,by);else next=R.close(s.s,req.input,by,{id:req.id});const writes=s.snap.filter(x=>P.canonical(x.data)!==P.canonical(next[x.name])).map(x=>({key:x.key,value:next[x.name],expected:x.raw}));P.commit(localStorage,writes,{actor:by});saved=true;});dialog.close();request=null;if(req.kind==='advance'){$('pay-advance-value').value='';$('pay-advance-reason').value='';$('pay-advance-paid').checked=false;$('pay-advance-override').checked=false;$('pay-advance-duplicate').checked=false;$('pay-advance-justification').value='';}if(req.kind==='close'){$('pay-reviewed').checked=false;$('pay-extra-lines').replaceChildren();}$('pay-calculation').replaceChildren();$('pay-calculation-message').textContent='';$('pay-advance-message').textContent='';refresh();$('pay-status').textContent='Registro salvo com histórico e cópia anterior. Nenhum pagamento bancário foi executado.';window.dispatchEvent(new Event('martins-financeiro-atualizado'));}catch(e){$('pay-dialog-message').textContent=(saved?'Registro salvo; atualize antes de repetir. ':'')+e.message;if(P.hasPending(localStorage)){dialog.close();window.martinsMostrarRecuperacao?.();}}finally{busy=false;$('pay-confirm').disabled=$('pay-back').disabled=false;}};
function extra(){const row=document.createElement('div');row.className='mf-grid pay-row';const date=document.createElement('input');date.type='date';date.setAttribute('aria-label','Data da hora extra');date.value=value('pay-end')||H.brDay();const h=document.createElement('input');h.type='number';h.min='.25';h.max='24';h.step='.25';h.dataset.field='hours';h.setAttribute('aria-label','Horas extras');const v=document.createElement('input');v.type='number';v.min='.01';v.step='.01';v.dataset.field='value';v.setAttribute('aria-label','Valor da hora extra em reais');const remove=document.createElement('button');remove.type='button';remove.textContent='Remover hora extra';remove.onclick=()=>row.remove();row.append(date,h,v,remove);$('pay-extra-lines').append(row);window.martinsFormatarDatas?.();}
$('pay-add-extra').onclick=extra;$('pay-add-allocation').onclick=()=>{try{actor();const s=sources(),row=document.createElement('div');row.className='mf-grid pay-row';const w=document.createElement('select');w.setAttribute('aria-label','Obra do rateio RH');opts(w,Object.keys(s.s.works).map(w=>({id:w,label:w})),'Selecione obra');const c=document.createElement('input');c.dataset.field='center';c.value='Mão de obra';c.maxLength=300;c.setAttribute('aria-label','Centro de custo do rateio RH');const v=document.createElement('input');v.dataset.field='value';v.type='number';v.min='.01';v.step='.01';v.setAttribute('aria-label','Valor do rateio RH em reais');const b=document.createElement('button');b.type='button';b.textContent='Remover rateio';b.onclick=()=>row.remove();row.append(w,c,v,b);$('pay-allocations').append(row);}catch(e){$('pay-status').textContent=e.message;}};
$('pay-advance-mode').onchange=()=>{$('pay-advance-existing').hidden=value('pay-advance-mode')!=='vincular';$('pay-advance-finance').hidden=value('pay-advance-mode')!=='registrar_pago';};$('pay-allocation-mode').onchange=()=>{$('pay-single').hidden=value('pay-allocation-mode')!=='work';$('pay-split').hidden=value('pay-allocation-mode')!=='split';};$('pay-person').onchange=()=>{$('pay-extra-lines').replaceChildren();$('pay-monthly-base').value='';$('pay-reviewed').checked=false;$('pay-calculation').replaceChildren();refresh();};$('pay-edit-person').onclick=()=>{if(value('pay-person'))window.abrirModalEditarColaborador?.(value('pay-person'));};$('pay-frequency').onclick=()=>window.navegarParaSecao?.('colaboradores','ponto');$('pay-refresh').onclick=refresh;$('pay-back').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{if(!busy)request=null;});
const oldTab=window.setSubtabColab;window.setSubtabColab=function(key){oldTab?.(key);panel.classList.toggle('hidden',key!=='remuneracao');if(key==='remuneracao'){tab.classList.add('text-amber-500','border-amber-500');$('colab-header-titulo')&&($('colab-header-titulo').textContent='Remuneração, Diárias e Vales');$('colab-header-desc')&&($('colab-header-desc').textContent='Apuração revisável pela Frequência e integração ao Contas a Pagar');refresh();}};tab.parentElement?.addEventListener('click',e=>{const b=e.target.closest('.subtab-colab-btn');if(b&&b!==tab)panel.classList.add('hidden');});function open(){window.fecharDrawerMenu?.();window.navegarParaSecao?.('colaboradores','remuneracao');window.setSubtabColab('remuneracao');panel.scrollIntoView({block:'start'});}tab.onclick=open;
function install(){if($('pay-drawer'))return;const drawer=$('drawer-menu-lateral')?.querySelector('.overflow-y-auto');if(!drawer)return;const b=document.createElement('button');b.id='pay-drawer';b.type='button';b.textContent='Remuneração, Diárias e Vales';b.onclick=open;const rh=[...drawer.querySelectorAll('span')].find(e=>e.textContent.trim()==='Recursos Humanos');(rh?.parentElement||drawer).append(b);}const oldDrawer=window.reorganizarDrawerLateralDefinitivo;if(typeof oldDrawer==='function')window.reorganizarDrawerLateralDefinitivo=function(...args){const r=oldDrawer.apply(this,args);install();return r;};document.addEventListener('DOMContentLoaded',install);install();window.addEventListener('martins-colaboradores-atualizados',()=>{if(!panel.classList.contains('hidden'))refresh();});window.addEventListener('storage',e=>{if([H.EMPLOYEES,J.KEYS.frequency,G.KEY,F.ACCOUNTS,R.ADVANCES,R.CLOSINGS,'cm_dados_obras_v2'].includes(e.key)){base=null;lastCalc=null;$('pay-status').textContent='Fontes alteradas em outra aba. Atualize e confira novamente antes de salvar.';}});for(const id of ['pay-advance-date','pay-end','pay-due'])$(id).value=H.brDay();$('pay-start').value=H.brDay().slice(0,8)+'01';
})();
